mapper.select:
SELECT COUNT(*)
FROM (SELECT SALES_NO
FROM SALES_ORDER S
LEFT JOIN EMP E ON S.EMP_NO = E.EMP_NO
LEFT JOIN CLIENT C ON S.CLIENT_NO = C.CLIENT_NO

	S.DEL_STATUS = 0


		AND C.CLIENT_NAME LIKE '%' || #{client_Name} || '%'


		AND E.EMP_NAME LIKE '%' || #{empName} || '%'


		AND S.OUT_STATUS = #{out_Status}


		AND S.SALES_DATE >= #{sales_Date_Start}


		AND S.SALES_DATE<= #{sales_Date_End}



)

SELECT S.SALES_NO, S.SALES_DATE, S.OUT_STATUS, S.DEL_STATUS , S.IN_DATE, H.CLIENT_NO, H.CLIENT_NAME, H.CLIENT_TEL , E.EMP_NO, E.EMP_NAME , I.PRODUCT_NO, I.SALES_ITEM_CNT, I.SALES_ITEM_OUTCNT , I.SALES_ITEM_COST, P.PRODUCT_NO, P.PRODUCT_NAME FROM ( SELECT ROWNUM RN , O.* FROM (SELECT * FROM SALES_ORDER WHERE DEL_STATUS = 0 ORDER BY SALES_NO DESC ) O )S LEFT JOIN CLIENT C ON S.CLIENT_NO = C.CLIENT_NO LEFT JOIN CLIENT_HIS H ON S.CLIENT_NO = H.CLIENT_NO AND COALESCE(S.MODIFY_DATE, S.IN_DATE) BETWEEN H.START_DATE AND H.END_DATE LEFT JOIN EMP E ON S.EMP_NO = E.EMP_NO LEFT JOIN SALES_ITEM I ON S.SALES_NO = I.SALES_NO LEFT JOIN PRODUCT P ON I.PRODUCT_NO = P.PRODUCT_NO
AND C.CLIENT_NAME LIKE '%' || #{client_Name} || '%'
AND E.EMP_NAME LIKE '%' || #{empName} || '%'
AND S.OUT_STATUS = #{out_Status}
AND RN >= #{start} AND RN <= #{end}
AND S.SALES_DATE >= #{sales_Date_Start}
AND S.SALES_DATE<= #{sales_Date_End}
ORDER BY S.SALES_NO DESC

mapper.insert:

INSERT INTO SALES_ITEM (SALES_NO, PRODUCT_NO, PRODUCT_VERSION, SALES_ITEM_CNT, SALES_ITEM_OUTCNT, SALES_ITEM_COST)

	SELECT #{sales_No}, #{item.product_No}, #{item.product_Version}, #{item.sales_Item_Cnt}, #{item.sales_Item_OutCnt}, #{item.sales_Item_Cost}
	FROM DUAL

mapper.update:
UPDATE SALES_ORDER
SET DEL_STATUS = 1
WHERE SALES_NO = #{sales_No}

BEGIN

	UPDATE SALES_ITEM
	SET SALES_ITEM_OUTCNT = #{item.sales_Item_Cnt}
	WHERE SALES_NO = #{item.sales_No} AND PRODUCT_NO = #{item.product_No};

END;

mapper.delete:
BEGIN

	DELETE FROM SALES_ITEM WHERE SALES_NO = #{item.sales_No} AND PRODUCT_NO = #{item.product_No} AND PRODUCT_VERSION = #{item.product_Version};

END;

