mapper.select:
SELECT i.item_no "parts_no", NVL(SUM(CASE WHEN i.inout_status = 0 THEN i.item_cnt -- IN (+) WHEN i.inout_status = 1 THEN -i.item_cnt -- OUT (−) ELSE 0 END), 0) "stock" FROM INVENTORY i WHERE i.item_status = 0 AND i.item_no IN
#{no}
GROUP BY i.item_no
